 static GameObject Build(string kind){string folder="Assets/Grounded119v2-"+kind;Check(!AssetDatabase.IsValidFolder(folder),"fresh "+folder);AssetDatabase.CreateFolder("Assets","Grounded119v2-"+kind);var root=new GameObject(kind);string input=Path.Combine(Root,kind=="absent"||kind=="badUV"||kind=="badPNG"?"Input96-"+kind:"Input119");var shader=Shader.Find("MapSharedProps/Lit");int n=kind=="prior"?GroundedBefore119.Build(input,folder,root.transform,shader):kind=="oldReader"?FrozenShoreReader95.Build(input,folder,root.transform,shader):GroundedPropsV1.Build(input,folder,root.transform,shader);Check(n==1&&root.transform.childCount==1,"one formal cluster "+kind);var o=root.transform.GetChild(0).gameObject;Check(o.GetComponentsInChildren<Collider>().Length==0,"intentionally non-solid shells "+kind);Check(o.GetComponentsInChildren<Renderer>().Length==1,"one combined renderer "+kind);return root;}
 public static void Run(){int exit=0;var output=Path.Combine(Root,"Evidence119Importv2");Directory.CreateDirectory(output);try{EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);Shader.SetGlobalVector("_TDPineWind",Vector4.zero);var beforeRoot=Build("prior");var afterRoot=Build("after");var before=beforeRoot.transform.GetChild(0).gameObject;var after=afterRoot.transform.GetChild(0).gameObject;var bm=before.GetComponent<MeshFilter>().sharedMesh;var am=after.GetComponent<MeshFilter>().sharedMesh;Check(ColliderSnapshot109.MeshHash(bm)==ColliderSnapshot109.MeshHash(am)&&bm.normals.SequenceEqual(am.normals)&&bm.uv.SequenceEqual(am.uv)&&bm.colors.SequenceEqual(am.colors),"all mesh data exact");Check(before.transform.localPosition==after.transform.localPosition&&before.transform.localRotation==after.transform.localRotation&&before.transform.localScale==after.transform.localScale,"source pose exact");var aMat=after.GetComponent<Renderer>().sharedMaterial;var bMat=before.GetComponent<Renderer>().sharedMaterial;var pb=new MaterialPropertyBlock();var pa=new MaterialPropertyBlock();before.GetComponent<Renderer>().GetPropertyBlock(pb);after.GetComponent<Renderer>().GetPropertyBlock(pa);Check(pb.GetColor("_BaseColor")==pa.GetColor("_BaseColor"),"tint exact");Check(aMat.GetTexture("_BaseMap")==bMat.GetTexture("_BaseMap"),"atlas shared");Check(aMat.IsKeywordEnabled("SMALL_PROP_LOCAL_LIGHTS")&&!bMat.IsKeywordEnabled("SMALL_PROP_LOCAL_LIGHTS"),"actual importer opt in");PrefabUtility.SaveAsPrefabAsset(after,"Assets/grounded119-after.prefab");
  foreach(string kind in new[]{"absent","badUV","badPNG","oldReader","repeat"}){var root=Build(kind);var o=root.transform.GetChild(0).gameObject;var m=o.GetComponent<Renderer>().sharedMaterial;if(kind=="repeat")Check(m.GetTexture("_BaseMap")==aMat.GetTexture("_BaseMap"),"repeat atlas shared");else Check(m.GetTexture("_BaseMap")==null||m.GetTexture("_BaseMap")==Texture2D.whiteTexture,"safe white fallback "+kind);Check(m.IsKeywordEnabled("SMALL_PROP_LOCAL_LIGHTS")== (kind!="oldReader"),"fallback lighting keyword "+kind);if(kind=="oldReader")Check(ColliderSnapshot109.MeshHash(o.GetComponent<MeshFilter>().sharedMesh)==ColliderSnapshot109.MeshHash(am),"old source geometry");UnityEngine.Object.DestroyImmediate(root);}
  var missing=new GameObject("missing");Check(GroundedPropsV1.Build(Path.Combine(Root,"NoGrounded119"),"Assets",missing.transform,Shader.Find("MapSharedProps/Lit"))==0&&missing.transform.childCount==0,"missing sidecar safe");UnityEngine.Object.DestroyImmediate(missing);
  var data=GroundedPropsV1.Read(Path.Combine(Root,"Input119/grounded_props.json"));int offset=0;foreach(var part in data.assets[0].parts){var pose=Array.Find(data.instances[0].parts,p=>p.id==part.id);var tr=Matrix4x4.TRS(new Vector3(pose.position[0],pose.position[1],pose.position[2]),new Quaternion(pose.rotation[0],pose.rotation[1],pose.rotation[2],pose.rotation[3]),new Vector3(pose.scale[0],pose.scale[1],pose.scale[2]));for(int k=0;k<part.positions.Length/3;k++)Check(Vector3.Distance(tr.MultiplyPoint3x4(new Vector3(part.positions[k*3],part.positions[k*3+1],part.positions[k*3+2])),after.transform.TransformPoint(am.vertices[offset+k]))<.00002f,"ground pose");offset+=part.positions.Length/3;}
  var camera=new GameObject("offscreen").AddComponent<Camera>();camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=Color.black;camera.aspect=4f/3;var target=after.GetComponent<Renderer>().bounds.center;camera.transform.position=target+new Vector3(.5f,.65f,-.7f);camera.transform.LookAt(target);camera.fieldOfView=38;camera.GetUniversalAdditionalCameraData().renderPostProcessing=false;RenderSettings.ambientMode=AmbientMode.Flat;RenderSettings.ambientLight=Color.black;RenderSettings.ambientIntensity=0;RenderSettings.skybox=null;RenderSettings.reflectionIntensity=0;
  var local=new GameObject("local").AddComponent<Light>();local.color=new Color(1,.65f,.3f);local.intensity=4;local.range=6;local.spotAngle=65;local.innerSpotAngle=40;local.shadowStrength=1;var sun=new GameObject("main").AddComponent<Light>();sun.type=LightType.Directional;sun.transform.rotation=Quaternion.Euler(45,30,0);sun.intensity=1;var blocker=GameObject.CreatePrimitive(PrimitiveType.Cube);blocker.GetComponent<Renderer>().shadowCastingMode=ShadowCastingMode.ShadowsOnly;var rows=new List<Row>();
  foreach(int mode in new[]{0,2}){var rp=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<UniversalRenderPipelineAsset>("Assets/Settings/PC_RPAsset.asset"));var rd=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<UniversalRendererData>("Assets/Settings/PC_Renderer.asset"));var sr=new SerializedObject(rd);sr.FindProperty("m_RenderingMode").intValue=mode;sr.ApplyModifiedPropertiesWithoutUndo();var sp=new SerializedObject(rp);sp.FindProperty("m_RendererDataList").GetArrayElementAtIndex(0).objectReferenceValue=rd;sp.FindProperty("m_AdditionalLightsRenderingMode").intValue=1;sp.ApplyModifiedPropertiesWithoutUndo();GraphicsSettings.defaultRenderPipeline=rp;QualitySettings.renderPipeline=rp;
   foreach(string light in new[]{"off","ambient","main","point","far","spot","spotOutside","pointShadow","spotShadow"}){sun.enabled=light=="main";RenderSettings.ambientLight=light=="ambient"?new Color(.15f,.15f,.15f):Color.black;RenderSettings.ambientIntensity=light=="ambient"?1:0;local.enabled=light!="off"&&light!="ambient"&&light!="main";local.type=light.StartsWith("spot")?LightType.Spot:LightType.Point;local.transform.position=target+new Vector3(-.5f,1,-.4f).normalized*(light=="far"?5:1.4f);local.transform.LookAt(target);if(light=="spotOutside")local.transform.Rotate(0,110,0,Space.World);bool shadow=light.EndsWith("Shadow");local.shadows=shadow?LightShadows.Hard:LightShadows.None;blocker.SetActive(shadow);blocker.transform.position=Vector3.Lerp(target,local.transform.position,.5f);blocker.transform.rotation=Quaternion.LookRotation(local.transform.position-target);blocker.transform.localScale=new Vector3(1.5f,1.5f,.08f);float[] mean=new float[2];byte[][] bytes=new byte[2][];
    for(int stage=0;stage<2;stage++){beforeRoot.SetActive(stage==0);afterRoot.SetActive(stage==1);var im=Shared117Review.Image(camera,640,480);mean[stage]=im.GetPixels().Average(c=>(c.r+c.g+c.b)/3);bytes[stage]=im.EncodeToPNG();if(mode==2&&(light=="point"||light=="spotShadow"||light=="main"))File.WriteAllBytes(Path.Combine(output,light+"-"+(stage==0?"before":"after")+".png"),bytes[stage]);UnityEngine.Object.DestroyImmediate(im);}
    if(new[]{"off","ambient","main","spotOutside"}.Contains(light))Check(bytes[0].SequenceEqual(bytes[1]),"unchanged "+light);if(light=="point"||light=="spot")Check(mean[1]>mean[0]+.001,"local response "+light);rows.Add(new Row{mode=mode,light=light,before=mean[0],after=mean[1]});}
   Func<string,float> gain=kind=>{var row=rows.Last(x=>x.mode==mode&&x.light==kind);return row.after-row.before;};Check(gain("far")<gain("point")*.6f,"distance");Check(gain("pointShadow")<gain("point")*.3f&&gain("spotShadow")<gain("spot")*.3f,"shadows");}
  Check(!ShaderUtil.ShaderHasError(aMat.shader),"shader compile");int unaffected=AssetDatabase.FindAssets("t:Prefab",new[]{"Assets/Imported117"}).Length;Check(unaffected==44,"unrelated44 present");AssetDatabase.SaveAssets();File.WriteAllText(Path.Combine(output,"checks.json"),JsonUtility.ToJson(new Report{pass=true,worldPoseExact=true,materialTintExact=true,sharedTexture=true,mainAmbientOffExact=true,cases=8,triangles=am.triangles.Length/3,colliders=0,unrelatedPrefabs=unaffected,rows=rows.ToArray(),limits=new[]{"OldReader95 source path exercised, not old binary; its missing optional texture is expected","Forward/Forward+ per-pixel modes; vertex mode untested","Existing unrelated44 assets retained; their builder and product data unchanged","Player/mobile/full gameplay untested; no GPU timing claim"}},true));
 }catch(Exception e){File.WriteAllText(Path.Combine(output,"error.txt"),e.ToString());Debug.LogException(e);exit=1;}finally{EditorApplication.Exit(exit);}}
